51: /*
52:   twolame_init
53:   Create a set of encoding options and return a pointer to this structure
54: 
55:   Returns NULL if unsuccessful (can't allocate memory)
56:   Otherwise returns pointer to memory block
57: */
58: twolame_options *twolame_init(void)
59: {
60:     twolame_options *newoptions = NULL;
61: 
62:     newoptions = (twolame_options *) TWOLAME_MALLOC(sizeof(twolame_options));
63:     if (newoptions == NULL) {
64:         return NULL;
65:     }
66: 
67:     memset(newoptions, 0, sizeof(twolame_options));
68: 
69:     newoptions->version = -1;
70:     newoptions->num_channels_in = 0;
71:     newoptions->num_channels_out = 0;
72:     newoptions->samplerate_in = 0;
73:     newoptions->samplerate_out = 0;
74: 
75:     newoptions->mode = TWOLAME_AUTO_MODE;   // Choose a proper mode later
76:     newoptions->psymodel = 3;
77:     newoptions->bitrate = -1;   // Default bitrate is set in init_params
78:     newoptions->vbr = FALSE;
79:     newoptions->freeformat = FALSE;
80:     newoptions->vbrlevel = 5.0;
81:     newoptions->athlevel = 0.0;
82: 
83:     newoptions->quickmode = FALSE;
84:     newoptions->quickcount = 10;
85:     newoptions->emphasis = TWOLAME_EMPHASIS_N;
86:     newoptions->private_extension = 0;
87:     newoptions->copyright = FALSE;
88:     newoptions->original = TRUE;
89:     newoptions->error_protection = FALSE;
90:     newoptions->padding = TWOLAME_PAD_NO;
91:     newoptions->do_dab = FALSE;
92:     newoptions->dab_crc_len = 2;
93:     newoptions->dab_xpad_len = 0;
94:     newoptions->verbosity = 2;
95:     newoptions->vbr_upper_index = 0;
96: 
97:     newoptions->slots_lag = 0.0;
98: 
99:     newoptions->scale = 1.0;    // scaling disabled
100:     newoptions->scale_left = 1.0;   // scaling disabled
101:     newoptions->scale_right = 1.0;  // scaling disabled
102: 
103:     newoptions->do_energy_levels = FALSE;
104:     newoptions->num_ancillary_bits = -1;
105: 
106:     newoptions->vbr_frame_count = 0;    // only used for debugging
107:     newoptions->tablenum = 0;
108: 
109:     newoptions->twolame_init = 0;
110:     newoptions->subband = NULL;
111:     newoptions->j_sample = NULL;
112:     newoptions->sb_sample = NULL;
113:     newoptions->psycount = 0;
114: 
115:     newoptions->p0mem = NULL;
116:     newoptions->p1mem = NULL;
117:     newoptions->p2mem = NULL;
118:     newoptions->p3mem = NULL;
119:     newoptions->p4mem = NULL;
120: 
121:     return (newoptions);
122: }
