434: /* Scale the samples in the frame sample buffer
435:    using the user specified values
436:    and downmix/upmix according to the number of input/output channels
437: */
438: static void scale_and_mix_samples(twolame_options * glopts)
439: {
440:     int num_samples = glopts->samples_in_buffer;
441:     int i;
442: 
443:     // apply scaling to both channels
444:     if (glopts->scale != 0 && glopts->scale != 1.0) {
445:         if (glopts->num_channels_in == 2)
446:             for (i = 0; i < num_samples; ++i) {
447:                 glopts->buffer[0][i] *= glopts->scale;
448:                 glopts->buffer[1][i] *= glopts->scale;
449:             }
450:         else
451:             for (i = 0; i < num_samples; ++i)
452:                 glopts->buffer[0][i] *= glopts->scale;
453:     }
454:     // apply scaling to channel 0 (left)
455:     if (glopts->scale_left != 0 && glopts->scale_left != 1.0) {
456:         for (i = 0; i < num_samples; ++i) {
457:             glopts->buffer[0][i] *= glopts->scale_left;
458:         }
459:     }
460:     // apply scaling to channel 1 (right)
461:     if (glopts->scale_right != 0 && glopts->scale_right != 1.0) {
462:         for (i = 0; i < num_samples; ++i) {
463:             glopts->buffer[1][i] *= glopts->scale_right;
464:         }
465:     }
466:     // Downmix to Mono if 2 channels in and 1 channel out
467:     if (glopts->num_channels_in == 2 && glopts->num_channels_out == 1) {
468:         for (i = 0; i < num_samples; ++i) {
469:             glopts->buffer[0][i] = ((long) glopts->buffer[0][i] + glopts->buffer[1][i]) / 2;
470:             glopts->buffer[1][i] = 0;
471:         }
472:     }
473:     // Upmix to Stereo if 2 channels out and 1 channel in
474:     if (glopts->num_channels_in == 1 && glopts->num_channels_out == 2) {
475:         for (i = 0; i < num_samples; ++i) {
476:             glopts->buffer[1][i] = glopts->buffer[0][i];
477:         }
478:     }
479: 
480: }
