713: 
714:             /* Update sample counts */
715:             glopts->samples_in_buffer += samples_to_copy;
716:             num_samples -= samples_to_copy;
717: 
718: 
719:             // is there enough to encode a whole frame ?
720:             if (glopts->samples_in_buffer >= TWOLAME_SAMPLES_PER_FRAME) {
