800: static void float32_to_short(const float in[], short out[], int num_samples, int stride)
801: {
802:     int n;
803: 
804:     for (n = 0; n < num_samples; n++) {
805:         int tmp = lrintf(in[n * stride] * 32768.0f);
806:         if (tmp > SHRT_MAX) {
807:             out[n] = SHRT_MAX;
808:         } else if (tmp < SHRT_MIN) {
809:             out[n] = SHRT_MIN;
810:         } else {
811:             out[n] = (short) tmp;
812:         }
813:     }
814: }
