947: {
948:     bit_stream *mybs = NULL;
949:     int mp2_size = 0;
950:     int i;
951: 
952:     if (glopts->samples_in_buffer == 0) {
953:         // No samples left over
954:         return 0;
955:     }
956:     // Create bit stream structure
957:     mybs = twolame_buffer_init(mp2buffer, mp2buffer_size);
958: 
959:     if (mybs != NULL) {
960:         // Pad out the PCM buffers with 0 and encode the frame
961:         for (i = glopts->samples_in_buffer; i < TWOLAME_SAMPLES_PER_FRAME; i++) {
962:             glopts->buffer[0][i] = glopts->buffer[1][i] = 0;
963:         }
964: 
965:         // Encode the frame
966:         mp2_size = encode_frame(glopts, mybs);
967:         glopts->samples_in_buffer = 0;
968: 
969:         // free up the bit stream buffer structure
970:         twolame_buffer_deinit(&mybs);
971:     }
972: 
973:     return mp2_size;
