49: /*
50:   new_extension()
51:   Puts a new extension name on a file name <filename>.
52:   Removes the last extension name, if any.
53: */
54: static void new_extension(char *filename, char *extname, char *newname)
55: {
56:     int found, dotpos;
57: 
58:     // First, strip the old extension
59:     dotpos = strlen(filename);
60:     found = 0;
61:     do {
62:         switch (filename[dotpos]) {
63:         case '.':
64:             found = 1;
65:             break;
66:         case '\\':
67:         case '/':
68:         case ':':
69:             found = -1;
70:             break;
71:         default:
72:             dotpos--;
73:             if (dotpos < 0)
74:                 found = -1;
75:             break;
76:         }
77:     } while (found == 0);
78: 
79:     if (found == -1) {
80:         strncpy(newname, filename, MAX_NAME_SIZE-1);
81:     }
82:     if (found == 1) {
83:         strncpy(newname, filename, dotpos);
84:         newname[dotpos] = '\0';
85:     }
86:     // Make sure there is room in the string for the
87:     // new filename and the extension
88:     if (strlen(newname) + strlen(extname) < MAX_NAME_SIZE-1) {
89:         strcat(newname, extname);
90:     }
91: }
