93: static char *format_filesize_string(char *string, int string_size, int filesize)
94: {
95: #define CONST_KB  (1024)
96: #define CONST_MB  (CONST_KB*CONST_KB)
97: #define CONST_GB  (CONST_KB*CONST_KB*CONST_KB)
98: 
99:     if (filesize < CONST_KB) {
100:         snprintf(string, string_size, "%d bytes", filesize);
101:     } else if (filesize < CONST_MB) {
102:         snprintf(string, string_size, "%2.2f KB", (float) filesize / CONST_KB);
103:     } else if (filesize < CONST_GB) {
104:         snprintf(string, string_size, "%2.2f MB", (float) filesize / CONST_MB);
105:     } else {
106:         snprintf(string, string_size, "%2.2f GB", (float) filesize / CONST_GB);
107:     }
108: 
109:     return string;
110: }
