235: /*
236:     build_shortopt_string()
237:     Creates a short args string from the options structure
238:     for use with getopt_long
239: */
240: static char *build_shortopt_string(char *shortstr, struct option *opts)
241: {
242:     int c = 0, n = 0;
243: 
244:     // And loop through the options again
245:     for (n = 0; opts[n].val != 0; n++) {
246:         if (opts[n].val > 0 && opts[n].val < 127) {
247:             shortstr[c++] = opts[n].val;
248:             if (opts[n].has_arg == optional_argument) {
249:                 fprintf(stderr, "gah: can't do optional arguments\n");
250:             } else if (opts[n].has_arg == required_argument) {
251:                 shortstr[c++] = ':';
252:             }
253:         }
254:     }
255: 
256:     // Finally - terminate the string
257:     shortstr[c] = '\0';
258: 
259:     return shortstr;
260: }
