264: /*
265:   parse_args()
266:   Parse the command line arguments
267: */
268: static void parse_args(int argc, char **argv, twolame_options * encopts)
269: {
270:     int ch = 0;
271:     int use_raw = FALSE;                  // use raw input?
272:     int sample_size = DEFAULT_SAMPLESIZE; // number of bits per sample for raw input
273:     int byteswap = FALSE;                 // swap endian on input audio ?
274:     char *shortopts;
275: 
276:     // process args
277:     struct option longopts[] = {
278: 
279:         // Input
280:         {"raw-input", no_argument, NULL, 'r'},
281:         {"byte-swap", no_argument, NULL, 'x'},
282:         {"samplerate", required_argument, NULL, 's'},
283:         {"samplesize", required_argument, NULL, 1000},
284:         {"channels", required_argument, NULL, 'N'},
285:         {"swap-channels", no_argument, NULL, 'g'},
286:         {"scale", required_argument, NULL, 1001},
287:         {"scale-l", required_argument, NULL, 1002},
288:         {"scale-r", required_argument, NULL, 1003},
289: 
290:         // Output
291:         {"mode", required_argument, NULL, 'm'},
292:         {"downmix", no_argument, NULL, 'a'},
293:         {"bitrate", required_argument, NULL, 'b'},
294:         {"psyc-mode", required_argument, NULL, 'P'},
295:         {"vbr", no_argument, NULL, 'v'},
296:         {"vbr-level", required_argument, NULL, 'V'},
297:         {"max-bitrate", required_argument, NULL, 'B'},
298:         {"ath", required_argument, NULL, 'l'},
299:         {"quick", required_argument, NULL, 'q'},
300:         {"single-frame", no_argument, NULL, 'S'},
301:         {"freeformat", no_argument, NULL, 1009},
302: 
303:         // Misc
304:         {"copyright", no_argument, NULL, 'c'},
305:         {"non-copyright", no_argument, NULL, 1004},
306:         {"non-original", no_argument, NULL, 'o'},
307:         {"original", no_argument, NULL, 1005},
308:         {"private-ext", no_argument, NULL, 1011},
309:         {"protect", no_argument, NULL, 'p'},
310:         {"padding", no_argument, NULL, 'd'},
311:         {"reserve-bits", required_argument, NULL, 'R'},
312:         {"deemphasis", required_argument, NULL, 'e'},
313:         {"energy", no_argument, NULL, 'E'},
314: 
315:         // Verbosity
316:         {"talkativity", required_argument, NULL, 't'},
317:         {"quiet", no_argument, NULL, 1006},
318:         {"brief", no_argument, NULL, 1007},
319:         {"verbose", no_argument, NULL, 1008},
320:         {"help", no_argument, NULL, 'h'},
321: 
322:         {NULL, 0, NULL, 0}
323:     };
324: 
325: 
326:     // Start by counting the number of options
327:     while (longopts[ch].val != 0) {
328:         ch++;
329:     }
330: 
331:     // Create a short options structure from the long one
332:     shortopts = (char *) malloc((ch * 2) + 1);
333:     if (shortopts == NULL) {
334:         fprintf(stderr,"Error: parse_args failed memory allocation\n");
335:         exit(ERR_MEM_ALLOC);
336:     }
337:     build_shortopt_string(shortopts, longopts);
338:     // fprintf(stderr,"shortopts: %s\n", shortopts);
339: 
340: 
341:     // Input format defaults
342:     memset(&sfinfo, 0, sizeof(sfinfo));
343:     sfinfo.format = 0;
344:     sfinfo.samplerate = DEFAULT_SAMPLERATE;
345:     sfinfo.channels = DEFAULT_CHANNELS;
346:     sfinfo.frames = 0;
347: 
348: 
349:     while ((ch = getopt_long(argc, argv, shortopts, longopts, NULL)) != -1) {
350:         switch (ch) {
351: 
352:         // Input
353:         case 'r':
354:             use_raw = 1;
355:             break;
356: 
357:         case 'x':
358:             byteswap = TRUE;
359:             break;
360: 
361:         case 's':
362:             twolame_set_out_samplerate(encopts, atoi(optarg));
363:             sfinfo.samplerate = atoi(optarg);
364:             break;
365: 
366:         case 1000:             // --samplesize
367:             sample_size = atoi(optarg);
368:             break;
369: 
370:         case 'N':
371:             sfinfo.channels = atoi(optarg);
372:             break;
373: 
374:         case 'g':
375:             channelswap = TRUE;
376:             break;
377: 
378:         case 1001:             // --scale
379:             twolame_set_scale(encopts, atof(optarg));
380:             break;
381: 
382:         case 1002:             // --scale-l
383:             twolame_set_scale_left(encopts, atof(optarg));
384:             break;
385: 
386:         case 1003:             // --scale-r
387:             twolame_set_scale_right(encopts, atof(optarg));
388:             break;
389: 
390: 
391: 
392:         // Output
393:         case 'm':
394:             if (*optarg == 's') {
395:                 twolame_set_mode(encopts, TWOLAME_STEREO);
396:             } else if (*optarg == 'd') {
397:                 twolame_set_mode(encopts, TWOLAME_DUAL_CHANNEL);
398:             } else if (*optarg == 'j') {
399:                 twolame_set_mode(encopts, TWOLAME_JOINT_STEREO);
400:             } else if (*optarg == 'm') {
401:                 twolame_set_mode(encopts, TWOLAME_MONO);
402:             } else if (*optarg == 'a') {
403:                 twolame_set_mode(encopts, TWOLAME_AUTO_MODE);
404:             } else {
405:                 fprintf(stderr, "Error: mode must be a/s/d/j/m not '%s'\n\n", optarg);
406:                 usage_long();
407:             }
408:             break;
409: 
410:         case 'a':              // downmix
411:             twolame_set_mode(encopts, TWOLAME_MONO);
412:             break;
413: 
414:         case 'b':
415:             twolame_set_bitrate(encopts, atoi(optarg));
416:             break;
417: 
418:         case 'P':
419:             twolame_set_psymodel(encopts, atoi(optarg));
420:             break;
421: 
422:         case 'v':
423:             twolame_set_VBR(encopts, TRUE);
424:             break;
425: 
426:         case 'V':
427:             twolame_set_VBR(encopts, TRUE);
428:             twolame_set_VBR_level(encopts, atof(optarg));
429:             break;
430: 
431:         case 'B':
432:             twolame_set_VBR_max_bitrate_kbps(encopts, atoi(optarg));
433:             break;
434: 
435:         case 'l':
436:             twolame_set_ATH_level(encopts, atof(optarg));
437:             break;
438: 
439:         case 'q':
440:             twolame_set_quick_mode(encopts, TRUE);
441:             twolame_set_quick_count(encopts, atoi(optarg));
442:             break;
443: 
444:         case 'S':
445:             single_frame_mode = TRUE;
446:             break;
447: 
448:         case 1009:
449:             twolame_set_freeformat(encopts, TRUE);
450:             break;
451: 
452:         // Miscellaneous
453:         case 'c':
454:             twolame_set_copyright(encopts, TRUE);
455:             break;
456:         case 1004:              // --non-copyright
457:             twolame_set_copyright(encopts, FALSE);
458:             break;
459:         case 'o':              // --non-original
460:             twolame_set_original(encopts, FALSE);
461:             break;
462:         case 1005:             // --original
463:             twolame_set_original(encopts, TRUE);
464:             break;
465:         case 1011:             // --private-ext
466:             twolame_set_extension(encopts, TRUE);
467:             break;
468:         case 'p':
469:             twolame_set_error_protection(encopts, TRUE);
470:             break;
471:         case 'd':
472:             twolame_set_padding(encopts, TWOLAME_PAD_ALL);
473:             break;
474:         case 'R':
475:             twolame_set_num_ancillary_bits(encopts, atoi(optarg));
476:             break;
477:         case 'e':
478:             if (*optarg == 'n')
479:                 twolame_set_emphasis(encopts, TWOLAME_EMPHASIS_N);
480:             else if (*optarg == '5')
481:                 twolame_set_emphasis(encopts, TWOLAME_EMPHASIS_5);
482:             else if (*optarg == 'c')
483:                 twolame_set_emphasis(encopts, TWOLAME_EMPHASIS_C);
484:             else {
485:                 fprintf(stderr, "Error: emphasis must be n/5/c not '%s'\n\n", optarg);
486:                 usage_long();
487:             }
488:             break;
489:         case 'E':
490:             twolame_set_energy_levels(encopts, TRUE);
491:             break;
492: 
493: 
494:         // Verbosity
495:         case 't':
496:             twolame_set_verbosity(encopts, atoi(optarg));
497:             break;
498: 
499:         case 1006:             // --quiet
500:             twolame_set_verbosity(encopts, 0);
501:             break;
502: 
503:         case 1007:             // --brief
504:             twolame_set_verbosity(encopts, 1);
505:             break;
506: 
507:         case 1008:             // --verbose
508:             twolame_set_verbosity(encopts, 4);
509:             break;
510: 
511:         case 'h':
512:             usage_long();
513:             break;
514: 
515:         default:
516:             usage_short();
517:             break;
518:         }
519:     }
520: 
521:     free(shortopts);
522: 
523:     // Look for the input and output file names
524:     argc -= optind;
525:     argv += optind;
526:     while (argc) {
527:         if (inputfilename[0] == '\0')
528:             strncpy(inputfilename, *argv, MAX_NAME_SIZE-1);
529:         else if (outputfilename[0] == '\0')
530:             strncpy(outputfilename, *argv, MAX_NAME_SIZE-1);
531:         else {
532:             fprintf(stderr, "excess argument: %s\n", *argv);
533:             usage_short();
534:         }
535: 
536:         argv++;
537:         argc--;
538:     }
539: 
540:     /* fill sfinfo struct in case of raw input file */
541:     if (use_raw) {
542:         sfinfo.format = SF_FORMAT_RAW;
543:         switch (sample_size) {
544:             case 8:
545:                 sfinfo.format |= SF_FORMAT_PCM_S8;
546:                 break;
547:             case 16:
548:                 sfinfo.format |= SF_FORMAT_PCM_16;
549:                 break;
550:             case 24:
551:                 sfinfo.format |= SF_FORMAT_PCM_24;
552:                 break;
553:             case 32:
554:                 sfinfo.format |= SF_FORMAT_PCM_32;
555:                 break;
556:             default:
557:                 fprintf(stderr, "Unsupported sample size: %d\n", sample_size);
558:                 usage_short();
559:         }
560: 
561:         if (byteswap) {
562:             union {
563:                 unsigned char  b[2];
564:                 unsigned short s;
565:             } detect_endian;
566: 
567:             detect_endian.b[0] = 0x34;
568:             detect_endian.b[1] = 0x12;
569:             if (detect_endian.s == 0x1234) {
570:                 /* we are on a little endian system */
571:                 sfinfo.format |= SF_ENDIAN_BIG;
572:             }
573:             else {
574:                 /* we are on a big endian system */
575:                 sfinfo.format |= SF_ENDIAN_LITTLE;
576:             }
577:         }
578:     }
579: 
580:     // Check that we now have input and output file names ok
581:     if (inputfilename[0] == '\0') {
582:         fprintf(stderr, "Missing input filename.\n");
583:         usage_short();
584:     }
585:     if (outputfilename[0] == '\0' && strcmp(inputfilename, "-") != 0) {
586:         // Create output filename from the inputfilename
587:         // and change the suffix
588:         new_extension(inputfilename, OUTPUT_SUFFIX, outputfilename);
589:     }
590:     if (outputfilename[0] == '\0') {
591:         fprintf(stderr, "Missing output filename.\n");
592:         usage_short();
593:     }
594:     // Check -r is supplied when reading from STDIN
595:     if (strcmp(inputfilename, "-") == 0 && !use_raw) {
596:         fprintf(stderr, "Error: please use RAW audio '-r' switch when reading from STDIN.\n");
597:         usage_short();
598:     }
599:     if (strcmp(inputfilename, "-") == 0)
600:         stdin_input = TRUE;
601: }
