627: static SNDFILE *open_input_sndfile(const char *filename, SF_INFO * sfinfo)
628: {
629:     // Open the input file by filename
630:     SNDFILE *file = sf_open(filename, SFM_READ, sfinfo);
631: 
632:     // Check for errors
633:     if (file == NULL) {
634:         fprintf(stderr, "Failed to open input file (%s):\n", filename);
635:         fprintf(stderr, "  %s\n", sf_strerror(NULL));
636:         exit(ERR_OPENING_INPUT);
637:     }
638: 
639:     /* enable scaling for floating point input files */
640:     sf_command(file, SFC_SET_SCALE_FLOAT_INT_READ, NULL, SF_TRUE);
