675: static void print_info_sndfile(SNDFILE *file, SF_INFO *sfinfo, unsigned int total_frames)
676: {
677:     SF_FORMAT_INFO format_info;
678:     SF_FORMAT_INFO subformat_info;
679:     char sndlibver[128];
680:     char duration[40];
681: 
682:     // Get the format
683:     format_info.format = sfinfo->format & SF_FORMAT_TYPEMASK;
684:     sf_command(file, SFC_GET_FORMAT_INFO, &format_info, sizeof(format_info));
685: 
686:     // Get the sub-format info
687:     subformat_info.format = sfinfo->format & SF_FORMAT_SUBMASK;
688:     sf_command(file, SFC_GET_FORMAT_INFO, &subformat_info, sizeof(subformat_info));
689: 
690:     // Get the version of libsndfile
691:     sf_command(file, SFC_GET_LIB_VERSION, sndlibver, sizeof(sndlibver));
692: 
693:     fprintf(stderr, "Input Format: %s, %s\n", format_info.name, subformat_info.name);
694:     if (total_frames) {
695:         // Get human readable duration of the input file
696:         format_duration_string(sfinfo, duration, sizeof(duration));
697:         fprintf(stderr, "Input Duration: %s\n", duration);
698:     }
699:     fprintf(stderr, "Input Library: %s\n", sndlibver);
