704: int main(int argc, char **argv)
705: {
706:     twolame_options *encopts = NULL;
707:     SNDFILE *inputfile = NULL;
708:     FILE *outputfile = NULL;
709:     short int *pcmaudio = NULL;
710:     unsigned int frame_count = 0;
711:     unsigned int total_samples = 0;
712:     unsigned int total_frames = 0;
713:     unsigned int total_bytes = 0;
714:     unsigned char *mp2buffer = NULL;
715:     int samples_read = 0;
716:     int mp2fill_size = 0;
717:     int audioReadSize = 0;
718:     char filesize[20];
719: 
720: 
721:     // Initialise Encoder Options Structure
722:     encopts = twolame_init();
723:     if (encopts == NULL) {
724:         fprintf(stderr, "Error: initializing libtwolame encoder failed.\n");
725:         exit(ERR_MEM_ALLOC);
726:     }
727:     // Get options and parameters from the command line
728:     parse_args(argc, argv, encopts);
729: 
730:     // Display the filenames
731:     print_filenames(twolame_get_verbosity(encopts));
732: 
733:     // Open the input file
734:     inputfile = open_input_sndfile(inputfilename, &sfinfo);
735: 
736:     // Calculate the size and number of frames we are going to encode
737:     if (sfinfo.frames && !stdin_input)
738:         total_frames = (sfinfo.frames -1) / TWOLAME_SAMPLES_PER_FRAME +1;
739:     else
740:         total_frames = 0;
741: 
742:     // Display input information
743:     if (twolame_get_verbosity(encopts) > 1) {
744:         print_info_sndfile(inputfile, &sfinfo, total_frames);
745:     }
746: 
747:     // Use information from input file to configure libtwolame
748:     twolame_set_num_channels(encopts, sfinfo.channels);
749:     twolame_set_in_samplerate(encopts, sfinfo.samplerate);
750: 
751:     // initialise twolame with this set of options
752:     if (twolame_init_params(encopts) != 0) {
753:         fprintf(stderr, "Error: configuring libtwolame encoder failed.\n");
754:         exit(ERR_INVALID_PARAM);
755:     }
756:     // display encoder settings
757:     twolame_print_config(encopts);
758: 
759: 
760:     // Allocate memory for the PCM audio data
761:     if ((pcmaudio = (short int *) calloc(AUDIO_BUF_SIZE, sizeof(short int))) == NULL) {
762:         fprintf(stderr, "Error: pcmaudio memory allocation failed\n");
763:         exit(ERR_MEM_ALLOC);
764:     }
765:     // Allocate memory for the encoded MP2 audio data
766:     if ((mp2buffer = (unsigned char *) calloc(MP2_BUF_SIZE, sizeof(unsigned char))) == NULL) {
767:         fprintf(stderr, "Error: mp2buffer memory allocation failed\n");
768:         exit(ERR_MEM_ALLOC);
769:     }
770: 
771:     // Open the output file
772:     outputfile = open_output_file(outputfilename);
773: 
774:     // Only encode a single frame of mpeg audio ?
775:     if (single_frame_mode)
776:         audioReadSize = TWOLAME_SAMPLES_PER_FRAME;
777:     else
778:         audioReadSize = AUDIO_BUF_SIZE;
779: 
780: 
781:     // Now do the reading/encoding/writing
782:     while ((samples_read = sf_read_short(inputfile, pcmaudio, audioReadSize)) > 0) {
783:         int bytes_out = 0;
784: 
785:         // Calculate the number of samples we have (per channel)
786:         samples_read /= sfinfo.channels;
787:         total_samples += (unsigned int)samples_read;
788: 
789:         // Do swapping of left and right channels if requested
790:         if (channelswap && sfinfo.channels == 2) {
791:             int i;
792:             for (i = 0; i < samples_read; i++) {
793:                 short tmp = pcmaudio[(2 * i)];
794:                 pcmaudio[(2 * i)] = pcmaudio[(2 * i) + 1];
795:                 pcmaudio[(2 * i) + 1] = tmp;
796:             }
797:         }
798:         // Encode the audio to MP2
799:         mp2fill_size =
800:             twolame_encode_buffer_interleaved(encopts, pcmaudio, samples_read, mp2buffer,
801:                                               MP2_BUF_SIZE);
802: 
803:         // Stop if we don't have any bytes (probably don't have enough audio for a full frame of
804:         // mpeg audio)
805:         if (mp2fill_size == 0)
806:             break;
807:         if (mp2fill_size < 0) {
808:             fprintf(stderr, "error while encoding audio: %d\n", mp2fill_size);
809:             exit(ERR_ENCODING);
810:         }
811:         // Check that a whole number of frame was written
812:         // if (mp2fill_size % frame_len != 0) {
813:         // fprintf(stderr,"error while encoding audio: non-whole number of frames written\n");
814:         // exit(ERR_ENCODING);
815:         // }
816: 
817:         // Write the encoded audio out
818:         bytes_out = fwrite(mp2buffer, sizeof(unsigned char), mp2fill_size, outputfile);
819:         if (bytes_out != mp2fill_size) {
820:             perror("error while writing to output file");
821:             exit(ERR_WRITING_OUTPUT);
822:         }
823:         total_bytes += bytes_out;
824: 
825:         // Only single frame ?
826:         if (single_frame_mode)
827:             break;
828: 
829: 
830:         // Display Progress
831:         frame_count = total_samples / TWOLAME_SAMPLES_PER_FRAME;
832:         if (twolame_get_verbosity(encopts) > 0) {
833:             fprintf(stderr, "\rEncoding frame: %i", frame_count);
834:             if (total_frames) {
835:                 fprintf(stderr, "/%i (%i%%)", total_frames, (frame_count * 100) / total_frames);
836:             }
837:             fflush(stderr);
838:         }
839:     }
840: 
841:     // Was there an error reading the audio?
842:     if (sf_error(inputfile) != SF_ERR_NO_ERROR) {
843:         fprintf(stderr, "Error reading from input file: %s\n", sf_strerror(inputfile));
844:     }
845: 
846:     //
847:     // Flush any remaining audio. (don't send any new audio data) There
848:     // should only ever be a max of 1 frame on a flush. There may be zero
849:     // frames if the audio data was an exact multiple of 1152
850:     //
851:     mp2fill_size = twolame_encode_flush(encopts, mp2buffer, MP2_BUF_SIZE);
852:     if (mp2fill_size > 0) {
853:         int bytes_out = fwrite(mp2buffer, sizeof(unsigned char), mp2fill_size, outputfile);
854:         frame_count++;
855:         if (bytes_out <= 0) {
856:             perror("error while writing to output file");
857:             exit(ERR_WRITING_OUTPUT);
858:         }
859:         else {
860:             if (twolame_get_verbosity(encopts) > 0) {
861:                 fprintf(stderr, "\rEncoding frame: %i", frame_count);
862:                 if (total_frames) {
863:                     fprintf(stderr, "/%i (%i%%)", total_frames, (frame_count * 100) / total_frames);
864:                 }
865:                 fflush(stderr);
866:             }
867:         }
868:         total_bytes += bytes_out;
869:     }
870: 
871:     if (twolame_get_verbosity(encopts) > 1) {
872:         format_filesize_string(filesize, sizeof(filesize), total_bytes);
873:         fprintf(stderr, "\nEncoding Finished.\n");
874:         fprintf(stderr, "Total bytes written: %s.\n", filesize);
875:     }
876:     // Close input and output streams
877:     sf_close(inputfile);
878:     fclose(outputfile);
879: 
880:     // Close the libtwolame encoder
881:     twolame_close(&encopts);
882: 
883: 
884:     // Free up memory
885:     free(pcmaudio);
886:     free(mp2buffer);
887: 
888:     return (ERR_NO_ERROR);
889: }
