40: int twolame_set_mode(twolame_options * glopts, TWOLAME_MPEG_mode mode)
41: {
42:     if (mode < TWOLAME_AUTO_MODE || mode > TWOLAME_MONO) {
43:         fprintf(stderr, "invalid mode %i\n", mode);
44:         return (-1);
45:     }
46:     glopts->mode = mode;
47:     return (0);
48: }
