55: const char *twolame_get_mode_name(twolame_options * glopts)
56: {
57:     static const char *mode_name[6] =
58:     { "Auto", "Stereo", "J-Stereo", "Dual-Channel", "Mono", "Illegal Mode" };
59:     int mode = glopts->mode;
60:     if (mode >= TWOLAME_AUTO_MODE && mode <= TWOLAME_MONO)
61:         return (mode_name[mode + 1]);
62:     else
63:         return (mode_name[5]);
64: }
