489: int twolame_set_DAB_scf_crc(twolame_options * glopts,
490:                             unsigned char *mp2buffer,
491:                             int mp2buffer_size)
492: {
493:     /* ScF-CRC field precedes two bytes of F-PAD */
494:     unsigned char *pTo = &mp2buffer[mp2buffer_size  - 3];
495: 
496:     if (glopts->dab_crc_len == 4)
497:     {
498:         *pTo-- = glopts->dab_crc[0];
499:         *pTo-- = glopts->dab_crc[1];
500:         *pTo-- = glopts->dab_crc[2];;
501:         *pTo-- = glopts->dab_crc[3];
502:     }
503:     else if (glopts->dab_crc_len == 2)
504:     {
505:         *pTo-- = glopts->dab_crc[0];
506:         *pTo-- = glopts->dab_crc[1];
507:     }
508:     else
509:     {
510:         fprintf(stderr, "Invalid size of DAB scf-crc field\n");
511:         return (-1);
512:     }
513:     return (0);
514: }
